/// Narrowest the catalog sidebar, which holds project drawers and session
/// cards, can be dragged.
const CATALOG_MIN_WIDTH: f32 = 220.0;
/// Widest the catalog sidebar can be dragged.
const CATALOG_MAX_WIDTH: f32 = 480.0;
/// Narrower than this, the catalog footer's Update button shows only its icon
/// so the settle notice beside it keeps its room.
const CATALOG_UPDATE_LABEL_MIN_WIDTH: f32 = 256.0;
/// Width the catalog always leaves for the session beside it.
const CATALOG_SESSION_MIN_WIDTH: f32 = 384.0;
/// Every session row shares one height and baseline.
const CARD_HEIGHT: f32 = 30.0;
/// How far the sidebar indents a project or folder for each folder it is in.
const CATALOG_INDENT: f32 = 12.0;
/// How far a session another session's agent started sits in from that one.
const SESSION_NEST_INDENT: f32 = 10.0;
/// How long the sidebar offers to undo a settle.
const SETTLE_UNDO_LIFETIME: Duration = Duration::from_secs(5);
/// Rows of the Settled shelf shown at first, and how many Show more adds.
const SETTLED_INITIAL_ROWS: usize = 10;
const SETTLED_MORE_ROWS: usize = 25;
const BROWSER_DIVIDER_WIDTH: f32 = 1.0;
/// How often working dots, pulses, and running timers advance. They move a
/// few times a second instead of on every frame: a repeating animation asks
/// for a frame at display rate, and each frame re-renders the whole window.
const PULSE_INTERVAL: Duration = Duration::from_millis(400);

/// Steps of the shared pulse, advanced only while something is working.
static PULSE_FRAME: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

thread_local! {
    /// Whether the last frame drew anything that moves with the pulse: a
    /// working dot, or a running timer. When nothing did, the pulse has no
    /// reason to redraw the window.
    static ANIMATION_DRAWN: Cell<bool> = const { Cell::new(false) };
}

/// Notes that this frame draws something the pulse moves.
fn mark_animated() {
    ANIMATION_DRAWN.with(|drawn| drawn.set(true));
}

fn pulse_frame() -> usize {
    mark_animated();
    PULSE_FRAME.load(std::sync::atomic::Ordering::Relaxed)
}

/// Opacity of a pulsing dot on the current pulse step.
fn pulse_opacity() -> f32 {
    [0.35, 0.65, 1.0, 0.65][pulse_frame() % 4]
}

fn browser_pane_width(requested: u16, window_width: f32) -> f32 {
    // Keep the session usable even at the window's minimum size.
    f32::from(requested).clamp(
        280.0,
        (window_width - BROWSER_DIVIDER_WIDTH - 460.0).clamp(280.0, 1000.0),
    )
}

/// `room` is the window width left of the browser. The catalog hides once that
/// drops below 640, so the session keeps its minimum wherever the catalog shows.
fn catalog_pane_width(requested: u16, room: f32) -> f32 {
    f32::from(requested).clamp(
        CATALOG_MIN_WIDTH,
        (room - CATALOG_SESSION_MIN_WIDTH).clamp(CATALOG_MIN_WIDTH, CATALOG_MAX_WIDTH),
    )
}

/// Keep room for the chat when sizing the bottom terminal.
fn bottom_terminal_height(requested: u16, available: f32) -> f32 {
    f32::from(requested).clamp(120.0, (available - 180.0).clamp(120.0, 600.0))
}

fn working_dot_alphas(frame: usize) -> [u8; 3] {
    let lit = frame % 4;
    std::array::from_fn(|index| if index < lit { 0xff } else { 0x4d })
}

/// Three dots that fill in one by one, in step with the shared pulse. The
/// size is inherited so the dots sit on the label's baseline.
fn working_dots(_instance: usize, color: u32) -> gpui::AnyElement {
    let highlights = working_dot_alphas(pulse_frame())
        .into_iter()
        .enumerate()
        .map(|(index, alpha)| {
            (
                index..index + 1,
                HighlightStyle {
                    color: Some(rgba((color << 8) | u32::from(alpha)).into()),
                    ..Default::default()
                },
            )
        });
    div()
        .w(px(13.0))
        .flex_none()
        .child(StyledText::new("...").with_highlights(highlights))
        .into_any_element()
}

