fn terminal_runtime_event(event: SessionEvent) -> (ChatEndpoint, &'static str, Value) {
    let endpoint = event.endpoint().into();
    let (name, body) = match event.kind {
        SessionEventKind::Opened {
            chat_id,
            terminal_id,
            title,
            agent,
            columns,
            rows,
        } => (
            "terminal-opened",
            serde_json::json!({
                "chat": chat_id,
                "terminal": terminal_id,
                "title": title,
                "agent": agent,
                "columns": columns,
                "rows": rows,
            }),
        ),
        SessionEventKind::Output {
            chat_id,
            terminal_id,
            data,
        } => (
            "terminal-output",
            serde_json::json!({
                "chat": chat_id,
                "terminal": terminal_id,
                "data": STANDARD.encode(data),
            }),
        ),
        SessionEventKind::Resized {
            chat_id,
            terminal_id,
            columns,
            rows,
        } => (
            "terminal-resized",
            serde_json::json!({
                "chat": chat_id,
                "terminal": terminal_id,
                "columns": columns,
                "rows": rows,
            }),
        ),
        SessionEventKind::Activity {
            chat_id,
            terminal_id,
            working,
        } => (
            "terminal-activity",
            serde_json::json!({
                "chat": chat_id,
                "terminal": terminal_id,
                "working": working,
                "terminal_working": working,
            }),
        ),
        SessionEventKind::Closed {
            chat_id,
            terminal_id,
        } => (
            "terminal-closed",
            serde_json::json!({"chat": chat_id, "terminal": terminal_id}),
        ),
    };
    (endpoint, name, body)
}

/// The shown terminal's text, colours and links, kept until its screen
/// changes. Rebuilding them walks the whole scrollback, so a redraw for
/// anything else (a blink, a token in the chat) reuses them instead.
struct TerminalRenderCache {
    revision: u64,
    text: SharedString,
    highlights: Vec<(Range<usize>, HighlightStyle)>,
    cursor: Option<Range<usize>>,
    links: Vec<(Range<usize>, String)>,
}

impl TerminalRenderCache {
    fn new(revision: u64, rendered: TerminalText) -> Self {
        let mut links = rendered
            .links
            .into_iter()
            .map(|link| (link.range, link.url))
            .collect::<Vec<_>>();
        let detected = markdown::web_links(&rendered.text)
            .into_iter()
            .filter(|(range, _)| {
                !links
                    .iter()
                    .any(|(native, _)| native.start < range.end && range.start < native.end)
            })
            .collect::<Vec<_>>();
        links.extend(detected);
        links.sort_by_key(|(range, _)| range.start);
        let highlights = rendered
            .spans
            .into_iter()
            .map(|span| {
                (
                    span.range,
                    HighlightStyle {
                        color: span.style.foreground.map(|color| rgb(color).into()),
                        background_color: span.style.background.map(|color| rgb(color).into()),
                        font_weight: span.style.bold.then_some(FontWeight::BOLD),
                        ..Default::default()
                    },
                )
            })
            .collect();
        Self {
            revision,
            text: rendered.text.into(),
            highlights,
            cursor: rendered.cursor,
            links,
        }
    }
}

fn insert_terminal_cursor_highlight(
    highlights: Vec<(Range<usize>, HighlightStyle)>,
    cursor: Option<(Range<usize>, HighlightStyle)>,
) -> Vec<(Range<usize>, HighlightStyle)> {
    let Some((cursor_range, cursor_style)) = cursor else {
        return highlights;
    };
    if cursor_range.is_empty() {
        return highlights;
    }

    let mut result = Vec::with_capacity(highlights.len() + 2);
    let mut inserted = false;
    for (range, style) in highlights {
        if range.end <= cursor_range.start {
            result.push((range, style));
        } else if cursor_range.end <= range.start {
            if !inserted {
                result.push((cursor_range.clone(), cursor_style));
                inserted = true;
            }
            result.push((range, style));
        } else {
            if range.start < cursor_range.start {
                result.push((range.start..cursor_range.start, style));
            }
            if !inserted {
                result.push((cursor_range.clone(), cursor_style));
                inserted = true;
            }
            if cursor_range.end < range.end {
                result.push((cursor_range.end..range.end, style));
            }
        }
    }
    if !inserted {
        result.push((cursor_range, cursor_style));
    }
    result
}

const TERMINAL_OUTPUT_PADDING: f32 = 16.0;

fn terminal_geometry(width: f32, height: f32, cell_width: f32, line_height: f32) -> (usize, usize) {
    let total_padding = TERMINAL_OUTPUT_PADDING * 2.0;
    let content_width = (width - total_padding).max(cell_width);
    let content_height = (height - total_padding).max(line_height);
    let columns = (content_width / cell_width.max(1.0)).floor() as usize;
    let rows = (content_height / line_height.max(1.0)).floor() as usize;
    (columns.clamp(20, 500), rows.clamp(4, 200))
}

fn terminal_scroll_is_at_bottom(scroll: &ScrollHandle) -> bool {
    let remaining = f32::from(scroll.max_offset().height) + f32::from(scroll.offset().y);
    remaining <= 2.0
}

fn terminal_mouse_scroll_bytes(delta_y: f32) -> Vec<u8> {
    let button = if delta_y > 0.0 {
        64
    } else if delta_y < 0.0 {
        65
    } else {
        return Vec::new();
    };
    format!("\x1b[<{button};1;1M").into_bytes()
}

#[derive(Clone, Debug, Default, Deserialize)]
struct GitStatus {
    branch: String,
    #[serde(default)]
    base: String,
    upstream: String,
    ahead: u64,
    conflicted: u64,
    clean: bool,
}

impl GitStatus {
    fn can_open_pull_request(&self) -> bool {
        self.clean
            && self.conflicted == 0
            && !self.branch.is_empty()
            && !matches!(self.branch.as_str(), "(detached)" | "(initial)")
            && !self.base.is_empty()
            && self.branch != self.base
            && !self.upstream.is_empty()
            && self.ahead == 0
    }
}

/// How long the session header trusts what it knows about a pull request. An
/// agent can open one from a terminal without the app hearing about it.
const CHAT_PULL_REQUEST_LIFETIME: Duration = Duration::from_secs(60);

/// What a host last said about the pull request of a chat's branch.
#[derive(Default)]
struct ChatPullRequest {
    requested_at: Option<Instant>,
    lookups: u64,
    branch: Option<String>,
    url: Option<String>,
}

impl ChatPullRequest {
    fn lookup_due(&self, now: Instant) -> bool {
        self.requested_at
            .is_none_or(|at| now.duration_since(at) >= CHAT_PULL_REQUEST_LIFETIME)
    }

    /// Starts a lookup, superseding any still running, and returns its token.
    fn start_lookup(&mut self, now: Instant) -> String {
        self.requested_at = Some(now);
        self.lookups += 1;
        self.lookup_token()
    }

    /// Hosts broadcast these answers, so the token also says which client asked.
    fn lookup_token(&self) -> String {
        static CLIENT: std::sync::OnceLock<u64> = std::sync::OnceLock::new();
        let client = CLIENT.get_or_init(|| {
            use std::hash::BuildHasher;
            std::collections::hash_map::RandomState::new().hash_one(std::process::id())
        });
        format!("pull-request-{client:x}-{}", self.lookups)
    }

    /// Lookups overlap and can finish in any order, so only the latest counts.
    /// A failed lookup says nothing, so it keeps the branch's known pull request.
    fn apply(&mut self, lookup: Option<&str>, answer: &Value) {
        if lookup != Some(self.lookup_token().as_str()) {
            return;
        }
        let Some(branch) = answer.get("branch").and_then(Value::as_str) else {
            return;
        };
        let same_branch = self.branch.as_deref() == Some(branch);
        match answer.get("url").and_then(Value::as_str) {
            Some(url) => self.url = (!url.is_empty()).then(|| url.to_owned()),
            None if !same_branch => self.url = None,
            None => {}
        }
        if !same_branch {
            self.branch = Some(branch.to_owned());
        }
    }

    fn url_for(&self, branch: &str) -> Option<&str> {
        (self.branch.as_deref() == Some(branch))
            .then_some(self.url.as_deref())
            .flatten()
    }
}

/// `#123` for a pull request's web address, or `PR` when it has no number in it.
fn pull_request_label(url: &str) -> String {
    let number = url
        .rsplit_once("/pull/")
        .map(|(_, rest)| {
            rest.chars()
                .take_while(char::is_ascii_digit)
                .collect::<String>()
        })
        .unwrap_or_default();
    if number.is_empty() {
        "PR".into()
    } else {
        format!("#{number}")
    }
}

/// How many linked pull requests the session header names before `+N`.
const HEADER_PULL_REQUEST_CHIPS: usize = 3;

const NOT_A_PULL_REQUEST_LINK: &str = "That is not a pull request link.";

