                    let id = device
                        .get("id")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_owned();
                    let name = device
                        .get("name")
                        .and_then(Value::as_str)
                        .unwrap_or("Device")
                        .to_owned();
                    let confirmed = panel.revoke_confirmation.as_deref() == Some(id.as_str());
                    div()
