    #[gpui::test]
    fn dragging_across_a_code_block_selects_its_text(cx: &mut gpui::TestAppContext) {
        let code = "first line of code\nsecond line of code";
        let cx = table_transcript(cx, 1100.0, &format!("Run this:\n\n```sh\n{code}\n```"));
        let bounds = cx.debug_bounds("native-code").unwrap();
        // Inside the block's padding: from the start of the first line to the
        // middle of the second.
        let from = point(bounds.left() + px(14.0), bounds.top() + px(20.0));
        let to = point(bounds.left() + px(60.0), bounds.top() + px(40.0));
        cx.simulate_mouse_move(from, None, gpui::Modifiers::default());
        cx.simulate_mouse_down(from, MouseButton::Left, gpui::Modifiers::default());
        cx.simulate_mouse_move(to, Some(MouseButton::Left), gpui::Modifiers::default());
        cx.simulate_mouse_up(to, MouseButton::Left, gpui::Modifiers::default());
        cx.run_until_parked();

        let selected = cx.update(|_, cx| TextSelection::selected(cx)).unwrap();
        assert!(
            selected.starts_with("first line of code\nsec"),
            "{selected:?}"
        );
        assert!(code.starts_with(&selected), "{selected:?}");
    }

    #[gpui::test]
    fn a_table_too_long_for_one_line_wraps_inside_aligned_columns(cx: &mut gpui::TestAppContext) {
        let prose = "A cell with far more to say than one line of the column can hold. ".repeat(3);
        let table = format!(
            "| Check | Result | Empty |\n|---|---|---|\n| Review | Clean | |\n| {prose} | {prose} | |"
        );
        let cx = table_transcript(cx, 1100.0, &table);

        let bounds = cx.debug_bounds("native-table").unwrap();
        for column in 0..3 {
            let header = cx
                .debug_bounds(format!("native-table-cell-0-{column}").leak())
                .unwrap();
            for row in 1..3 {
                let cell = cx
                    .debug_bounds(format!("native-table-cell-{row}-{column}").leak())
                    .unwrap();
                assert_eq!(cell.left(), header.left());
                assert_eq!(cell.size.width, header.size.width);
            }
        }
        let last = cx.debug_bounds("native-table-cell-2-2").unwrap();
        assert!(
            last.right() <= bounds.right(),
            "the table fits its reading column"
        );
        let short = cx.debug_bounds("native-table-cell-1-0").unwrap();
        let wrapped = cx.debug_bounds("native-table-cell-2-0").unwrap();
        assert!(
            wrapped.size.height > short.size.height,
            "a long cell wraps in place"
        );
    }

    #[gpui::test]
    fn a_table_with_too_many_columns_scrolls_instead_of_crushing_them(
        cx: &mut gpui::TestAppContext,
    ) {
        let row = |cell: &str| format!("|{}", format!(" {cell} |").repeat(14));
        let table = format!("{}\n{}\n{}", row("head"), row("---"), row("cell"));
        let cx = table_transcript(cx, 900.0, &table);

        let bounds = cx.debug_bounds("native-table").unwrap();
        let first = cx.debug_bounds("native-table-cell-1-0").unwrap();
        assert_eq!(first.size.width, px(TABLE_COLUMN_MIN_WIDTH));
        assert!(first.left() + px(TABLE_COLUMN_MIN_WIDTH * 14.0) > bounds.right());
    }

    #[gpui::test]
    fn compact_transcript_keeps_its_scroll_viewport_above_the_composer(
        cx: &mut gpui::TestAppContext,
    ) {
        install_embedded_fonts(cx.text_system()).unwrap();
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, _| {
            desktop.model = grouped_workspace_fixture();
            desktop.model.select_chat("implementation");
            desktop.model.backend = "codex".into();
            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "atlas".into(), chat_id: "implementation".into(), agent: AgentCli::Codex,
            };
            desktop.settings.browser_sessions.clear();
            desktop.transcript_snapshot.messages = Arc::new((0..12).map(|index| Message::new(
                Some(index), "assistant",
                format!("Message {index}. {}", "A paragraph that wraps at a narrow viewport and remains readable while scrolling. ".repeat(8)),
                None,
            )).collect());
            desktop.transcript_loaded = true;
            desktop.transcript_loading = false;
            desktop.sync_transcript_count(true);
        });
        cx.simulate_resize(size(px(760.0), px(560.0)));
        cx.run_until_parked();
        let composer = cx.debug_bounds("chat-composer").unwrap();
        desktop.update(cx, |desktop, _| {
            let viewport = desktop.transcript.viewport_bounds();
            assert!(viewport.size.height > px(0.0));
            assert!(
                viewport.bottom() <= composer.top(),
                "transcript must not paint under the composer"
            );
            assert!(
                desktop.transcript_pinned(),
                "the loaded transcript follows its newest message"
            );
            assert!(
                desktop.transcript.max_offset_for_scrollbar().height > px(0.0),
                "overflow remains scrollable"
            );
            desktop.transcript.scroll_to(ListOffset {
                item_ix: 0,
                offset_in_item: px(0.0),
            });
        });
        cx.update(|window, cx| {
            window.refresh();
            window.draw(cx).clear();
        });
        desktop.update(cx, |desktop, _| {
            let first = desktop
                .transcript
                .bounds_for_item(0)
                .expect("first message is reachable");
            assert!(first.top() >= desktop.transcript.viewport_bounds().top() - px(1.0));
        });
    }

    #[gpui::test]
    fn going_into_the_open_chat_lands_on_its_newest_message(cx: &mut gpui::TestAppContext) {
        install_embedded_fonts(cx.text_system()).unwrap();
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, _| {
            desktop.model = grouped_workspace_fixture();
            desktop.model.select_chat("implementation");
            desktop.model.backend = "codex".into();
            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "atlas".into(),
                chat_id: "implementation".into(),
                agent: AgentCli::Codex,
            };
            desktop.settings.browser_sessions.clear();
            desktop.transcript_snapshot.messages = Arc::new(
                (0..12)
                    .map(|index| {
                        Message::new(
                            Some(index),
                            "assistant",
                            format!("Message {index}. {}", "A long paragraph. ".repeat(40)),
                            None,
                        )
                    })
                    .collect(),
            );
            desktop.transcript_loaded = true;
            desktop.transcript_loading = false;
            desktop.sync_transcript_count(true);
        });
        cx.simulate_resize(size(px(760.0), px(560.0)));
        cx.run_until_parked();
        let scroll_back = |desktop: &mut XdDesktop| {
            desktop.transcript.scroll_to(ListOffset {
                item_ix: 0,
                offset_in_item: px(0.0),
            });
            assert!(!desktop.transcript_pinned());
        };

        // A tree update that routes to the open chat leaves the reader's place.
        desktop.update(cx, |desktop, cx| {
            scroll_back(desktop);
            desktop.select_minimal_session(
                "atlas".into(),
                "implementation".into(),
                AgentCli::Codex,
                cx,
            );
            assert!(!desktop.transcript_pinned());
        });

        // Going into it, from the sidebar say, shows the newest message.
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            desktop.open_minimal_session(
                "atlas".into(),
                "implementation".into(),
                AgentCli::Codex,
                window,
                cx,
            );
            assert!(desktop.transcript_pinned());
        });
    }

    /// A host on one end of a socket, and the requests it receives.
    #[cfg(unix)]
    fn socket_host(
        name: &str,
    ) -> (
        HostHandle,
        std::io::BufReader<std::os::unix::net::UnixStream>,
    ) {
        let (client, server) = std::os::unix::net::UnixStream::pair().unwrap();
        server
            .set_read_timeout(Some(Duration::from_secs(1)))
            .unwrap();
        let (host, _updates) =
            HostHandle::connect_io(client.try_clone().unwrap(), client, PathBuf::from(name));
        (host, std::io::BufReader::new(server))
    }

    /// The next messages request the host received.
    #[cfg(unix)]
    fn next_messages_request(
        requests: &mut std::io::BufReader<std::os::unix::net::UnixStream>,
    ) -> Value {
        use std::io::BufRead;
        loop {
            let mut line = String::new();
            requests
                .read_line(&mut line)
                .expect("a messages request must be sent");
            let request: Value = serde_json::from_str(&line).unwrap();
            if request["op"] == "messages" {
                return request;
            }
        }
    }

    #[cfg(unix)]
    fn message_page(
        ids: std::ops::RangeInclusive<i64>,
        has_older: bool,
        has_newer: bool,
    ) -> serde_json::Map<String, Value> {
        let messages = ids
            .map(|id| serde_json::json!({"id": id, "role": "assistant", "content": format!("Message {id}")}))
            .collect::<Vec<_>>();
        serde_json::json!({"ok": true, "messages": messages, "has_older": has_older, "has_newer": has_newer})
            .as_object()
            .unwrap()
            .clone()
    }

    #[cfg(unix)]
    fn reply_messages(
        desktop: &mut XdDesktop,
        cursor: MessageCursor,
        page: serde_json::Map<String, Value>,
        cx: &mut Context<XdDesktop>,
    ) {
        let chat_id = "implementation".into();
        desktop.handle_reply(RequestKind::Messages { chat_id, cursor }, page, None, cx);
    }

    /// Shows the implementation chat's newest page through [host], or an
    /// older window when [has_newer], then pages further back.
    #[cfg(unix)]
    fn page_back_through_implementation(
        desktop: &mut XdDesktop,
        host: &HostHandle,
        has_newer: bool,
        cx: &mut Context<XdDesktop>,
    ) {
        desktop.model = grouped_workspace_fixture();
        desktop.model.select_chat("implementation");
        desktop.model.connected = true;
        desktop.minimal_route = MinimalRoute::Cli {
            project_id: "atlas".into(),
            chat_id: "implementation".into(),
            agent: AgentCli::Codex,
        };
        desktop.host = Some(host.clone());
        reply_messages(
            desktop,
            MessageCursor::Tail,
            message_page(10..=19, true, has_newer),
            cx,
        );
        assert_eq!(desktop.transcript_has_newer, has_newer);
        desktop.request_older_messages();
        assert!(desktop.transcript_page_loading);
    }

    #[cfg(unix)]
    #[gpui::test]
    fn an_agent_opens_in_its_own_tab_and_messages_go_through_its_lead(
        cx: &mut gpui::TestAppContext,
    ) {
        use std::io::BufRead;
        let (host, mut requests) = socket_host("agent-tab-test");
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        let record = r#"subagent_run
{"key":"toolu_1","task_id":"a1b2","provider":"Claude","agent":"Explore","description":"Read the \"parser\"","status":"running","steps":[{"tool":"Read","text":"src/parser.rs"}]}"#;
        // Claude has not reported this one's id yet, so it takes no messages.
        let unaddressed = r#"subagent_run
{"key":"toolu_2","provider":"Claude","agent":"Explore","description":"Check the lexer","status":"running"}"#;
        desktop.update(cx, |desktop, cx| {
            page_back_through_implementation(desktop, &host, false, cx);
            desktop.model.messages = vec![
                Message::new(Some(1), "user", "Map the parser", None),
                Message::new(Some(2), "tool", record, None),
                Message::new(Some(4), "tool", unaddressed, None),
                Message::new(
                    Some(3),
                    "user",
                    agent_relay::format("Read 'parser'", "a1b2", "Earlier note"),
                    None,
                ),
            ];
            desktop.transcript_snapshot.sync_messages(&desktop.model);
        });
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            // With no box to type in, focus stays on the tab itself.
            desktop.open_agent_tab("toolu_2".into(), window, cx);
            assert!(desktop.agent_view_focus.is_focused(window));
            desktop.open_agent_tab("toolu_1".into(), window, cx);
            assert!(
                desktop
                    .agent_input
                    .read(cx)
                    .focus_handle(cx)
                    .is_focused(window)
            );
            assert_eq!(desktop.open_agent_key(), Some("toolu_1"));
            assert_eq!(
                desktop.agent_messages("a1b2"),
                vec![("Earlier note".to_owned(), false)]
            );
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("agent-composer").is_some());
        // An agent whose record is not loaded draws a note, and holds focus
        // there even after the chat's composer had it.
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            desktop.open_agent_tab("toolu_gone".into(), window, cx);
            window.focus(&desktop.composer_input.read(cx).focus_handle(cx));
        });
        cx.run_until_parked();
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            assert!(desktop.agent_view_focus.is_focused(window));
            desktop.close_agent_tab("toolu_gone", cx);
            desktop.open_agent_tab("toolu_1".into(), window, cx);
        });
        cx.run_until_parked();
        // Back from another chat, focus is on this chat's composer, which the
        // agent tab hides; drawing the tab hands it to the agent's box.
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            window.focus(&desktop.composer_input.read(cx).focus_handle(cx));
        });
        cx.run_until_parked();
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            assert!(
                desktop
                    .agent_input
                    .read(cx)
                    .focus_handle(cx)
                    .is_focused(window)
            );
        });
        desktop.update(cx, |desktop, cx| {
            desktop
                .agent_drafts
                .insert("toolu_1".into(), "  Check the lexer too ".into());
            desktop.send_agent_message(cx);
            assert!(!desktop.agent_drafts.contains_key("toolu_1"));
        });
        let send = loop {
            let mut line = String::new();
            requests
                .read_line(&mut line)
                .expect("a send request must reach the host");
            let request: Value = serde_json::from_str(&line).unwrap();
            if request["op"] == "send" {
                break request;
            }
        };
        assert_eq!(send["chat"], "implementation");
        let relay = agent_relay::parse(send["text"].as_str().unwrap()).unwrap();
        assert_eq!(relay.address, "a1b2");
        assert_eq!(relay.description, "Read the 'parser'");
        assert_eq!(relay.text, "Check the lexer too");
        desktop.update(cx, |desktop, cx| {
            // A send the host turns away puts the words back in the agent's
            // box, even while another chat is in front.
            desktop
                .agent_drafts
                .insert("toolu_1".into(), "typed since".into());
            let shown = desktop.open_agent.take();
            desktop.restore_pending_send(cx);
            desktop.open_agent = shown;
            assert_eq!(
                desktop.agent_drafts["toolu_1"],
                "Check the lexer too\ntyped since"
            );
            assert_eq!(
                desktop.agent_input.read(cx).text(),
                "Check the lexer too\ntyped since"
            );
            assert!(desktop.composer.is_empty());
            desktop.close_agent_tab("toolu_1", cx);
            assert_eq!(desktop.open_agent_key(), None);
            assert_eq!(desktop.agent_tabs["implementation"], vec!["toolu_2"]);
        });
    }

    #[cfg(unix)]
    #[gpui::test]
    fn reopening_a_chat_paged_back_asks_for_the_newest_page_after_the_one_loading(
        cx: &mut gpui::TestAppContext,
    ) {
        let (host, mut requests) = socket_host("tail-after-page-test");
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, cx| {
            page_back_through_implementation(desktop, &host, true, cx);
            assert_eq!(next_messages_request(&mut requests)["before"], 10);
        });

        // Going into the chat while that page loads still asks for the newest.
        cx.update_window_entity(&desktop, |desktop, window, cx| {
            desktop.open_minimal_session(
                "atlas".into(),
                "implementation".into(),
                AgentCli::Codex,
                window,
                cx,
            );
            assert!(desktop.transcript_tail_pending);
        });
        desktop.update(cx, |desktop, cx| {
            reply_messages(
                desktop,
                MessageCursor::Before(10),
                message_page(5..=9, false, true),
                cx,
            );
            let tail = next_messages_request(&mut requests);
            assert!(tail.get("before").is_none() && tail.get("after").is_none());
            reply_messages(
                desktop,
                MessageCursor::Tail,
                message_page(30..=39, true, false),
                cx,
            );
            assert!(!desktop.transcript_has_newer);
            assert!(!desktop.transcript_tail_pending);
            assert_eq!(
                desktop.model.messages.last().and_then(|message| message.id),
                Some(39)
            );
            assert!(desktop.transcript_pinned());
        });
    }

    #[cfg(unix)]
    #[gpui::test]
    fn jumping_to_latest_while_an_older_page_loads_asks_for_the_newest_if_it_leaves(
        cx: &mut gpui::TestAppContext,
    ) {
        let (host, mut requests) = socket_host("jump-during-page-test");
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, cx| {
            // The newest rows are here when the reader jumps, but the older
            // page on its way leaves the window short of them.
            page_back_through_implementation(desktop, &host, false, cx);
            assert_eq!(next_messages_request(&mut requests)["before"], 10);
            desktop.jump_to_latest(cx);
            reply_messages(
                desktop,
                MessageCursor::Before(10),
                message_page(5..=9, false, true),
                cx,
            );
            assert!(desktop.transcript_has_newer);
            let tail = next_messages_request(&mut requests);
            assert!(tail.get("before").is_none() && tail.get("after").is_none());
        });
    }

    #[cfg(unix)]
    #[gpui::test]
    fn a_reconnect_asks_again_for_a_newest_page_that_never_arrived(cx: &mut gpui::TestAppContext) {
        let (host, mut requests) = socket_host("tail-across-reconnect-test");
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, cx| {
            page_back_through_implementation(desktop, &host, true, cx);
            assert_eq!(next_messages_request(&mut requests)["before"], 10);
            desktop.jump_to_latest(cx);
            reply_messages(
                desktop,
                MessageCursor::Before(10),
                message_page(5..=9, false, true),
                cx,
            );
            let tail = next_messages_request(&mut requests);
            assert!(tail.get("before").is_none() && tail.get("after").is_none());

            // The connection drops before the newest page comes back.
            desktop.handle_host_update(
                HostUpdate::Disconnected {
                    message: "Connection lost".into(),
                },
                desktop.connection_generation,
                cx,
            );
            desktop.host = Some(host.clone());
            desktop.handle_host_update(
                HostUpdate::Connected {
                    path: PathBuf::from("reconnected"),
                },
                desktop.connection_generation,
                cx,
            );
            let again = next_messages_request(&mut requests);
            assert!(again.get("before").is_none() && again.get("after").is_none());
        });
    }

