    #[cfg(unix)]
    #[gpui::test]
    fn a_lost_connection_keeps_earlier_answers_and_gives_back_the_last(
        cx: &mut gpui::TestAppContext,
    ) {
        let (desktop, cx, _requests, _updates) = docked_ask_fixture(cx);
        let request = serde_json::json!({
            "request_id": "ask-1",
            "method": "item/tool/requestUserInput",
            "params": {"questions": [
                {"id": "q0", "question": "Which region?", "options": []},
                {"id": "q1", "question": "Which database?", "options": []},
            ]},
        });
        // The first answer is kept; the last is on its way when the
        // connection drops.
        answer_with_words(&desktop, request.clone(), "Staging only", cx);
        answer_with_words(&desktop, request.clone(), "Use Postgres", cx);
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            assert!(desktop.interaction_submitting());
            assert!(desktop.composer.is_empty());
            let generation = desktop.connection_generation;
            desktop.handle_host_update(
                HostUpdate::Disconnected {
                    message: "The host went away.".into(),
                },
                generation,
                cx,
            );
            assert!(!desktop.interaction_submitting());
            assert_eq!(desktop.composer, "Use Postgres", "the last words come back");
            assert_eq!(
                desktop.kept_answer("ask-1", "q0"),
                Some("Staging only"),
                "the earlier answer outlives the reconnect"
            );
            let (_, question, ..) = desktop.pending_input_question().unwrap();
            assert_eq!(question["id"], "q1");
        });
    }

    #[cfg(unix)]
    #[gpui::test]
    fn answers_kept_on_one_host_never_reach_another_with_the_same_ids(
        cx: &mut gpui::TestAppContext,
    ) {
        let (desktop, cx, _requests, _updates) = docked_ask_fixture(cx);
        let paired_to = |fingerprint: &str| xd_transport::RemoteCredentials {
            host: "192.168.1.20".into(),
            port: 7878,
            fingerprint: fingerprint.into(),
            token: "token".into(),
        };
        // Answering on a paired host, A.
        cx.update_window_entity(&desktop, |desktop, _, _| {
            desktop.active_endpoint = ChatEndpoint::Remote;
            desktop.remote_host = desktop.host.clone();
            desktop.settings.remote_credentials = Some(paired_to("host-a"));
        });
        let request = serde_json::json!({
            "request_id": "ask-1",
            "method": "item/tool/requestUserInput",
            "params": {"questions": [
                {"id": "q0", "question": "Which region?", "options": []},
                {"id": "q1", "question": "Which database?", "options": []},
            ]},
        });
        answer_with_words(&desktop, request, "Staging only", cx);
        let host_a = cx.update_window_entity(&desktop, |desktop, _, cx| {
            assert_eq!(desktop.kept_answer("ask-1", "q0"), Some("Staging only"));
            let host_a = desktop.host_identity(ChatEndpoint::Remote);
            // Host B at the same address, with a copy of A's chats and the
            // same request waiting.
            desktop.forget_interaction_answers(None, cx);
            desktop.settings.remote_credentials = Some(paired_to("host-b"));
            assert!(desktop.kept_answer("ask-1", "q0").is_none());
            let (_, question, ..) = desktop.pending_input_question().unwrap();
            assert_eq!(question["id"], "q0", "B asks from the start");
            // Words given back for A wait for A, not B's composer.
            desktop.give_back_answer(host_a.clone(), "implementation".into(), "For A".into(), cx);
            assert!(desktop.composer.is_empty());
            host_a
        });
        // Back on A, its answer and words are there.
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            desktop.settings.remote_credentials = Some(paired_to("host-a"));
            assert_eq!(desktop.host_identity(ChatEndpoint::Remote), host_a);
            assert_eq!(desktop.kept_answer("ask-1", "q0"), Some("Staging only"));
            desktop.apply_answer_restore(cx);
            assert_eq!(desktop.composer, "For A");
        });
    }

    #[cfg(unix)]
    #[gpui::test]
    fn a_secret_being_typed_survives_a_refresh_but_not_its_question(cx: &mut gpui::TestAppContext) {
        let (desktop, cx, _requests, _updates) = docked_ask_fixture(cx);
        let secret = |request_id: &str| {
            serde_json::json!({
                "request_id": request_id,
                "method": "item/tool/requestUserInput",
                "params": {"questions": [
                    {"id": "q0", "question": "Your token?", "isSecret": true, "options": []},
                ]},
            })
        };
        let refresh = |desktop: &Entity<XdDesktop>,
                       interactions: Vec<Value>,
                       cx: &mut gpui::VisualTestContext| {
            cx.update_window_entity(desktop, |desktop, _, cx| {
                // The chat's state again, as an option change or a reload
                // brings it, while the turn still runs.
                desktop.handle_reply(
                    RequestKind::Chat {
                        chat_id: "implementation".into(),
                    },
                    serde_json::json!({
                        "ok": true,
                        "working": true,
                        "backend": "codex",
                        "interactions": interactions,
                    })
                    .as_object()
                    .unwrap()
                    .clone(),
                    None,
                    cx,
                );
            });
            redraw(cx);
        };
        let typed = |desktop: &Entity<XdDesktop>, cx: &mut gpui::VisualTestContext| {
            cx.update_window_entity(desktop, |desktop, _, cx| {
                (
                    desktop.question_answer.clone(),
                    desktop.secret_question_input.read(cx).text().to_owned(),
                )
            })
        };
        refresh(&desktop, vec![secret("ask-1")], cx);
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            desktop
                .secret_question_input
                .update(cx, |input, cx| input.set_text("hunter2", cx));
            desktop.secret_answer_changed("hunter2".into(), cx);
        });
        refresh(&desktop, vec![secret("ask-1")], cx);
        assert_eq!(typed(&desktop, cx), ("hunter2".into(), "hunter2".into()));
        // Another question in its place: the secret was not typed for it.
        refresh(&desktop, vec![secret("ask-2")], cx);
        assert_eq!(typed(&desktop, cx), (String::new(), String::new()));
    }

    #[cfg(unix)]
    #[gpui::test]
    fn a_refused_answer_opens_its_question_again_with_the_words_kept(
        cx: &mut gpui::TestAppContext,
    ) {
        let (desktop, cx, mut requests, updates) = docked_ask_fixture(cx);
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            desktop.set_composer_text("Staging only".into(), cx);
            desktop.model.start_working();
            desktop.model.interactions = vec![serde_json::json!({
                "request_id": "ask-1",
                "method": "item/tool/requestUserInput",
                "params": {"questions": [
                    {"id": "q0", "question": "Which region?", "options": [
                        {"label": "us-east-1"},
                        {"label": "eu-west-1"},
                    ]},
                ]},
            })];
        });
        redraw(cx);
        let send = cx.debug_bounds("native-send-message").unwrap();
        cx.simulate_click(send.center(), gpui::Modifiers::default());
        cx.run_until_parked();
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            // Gone from the composer like a sent message. On its way, the
            // question stays in view, but nothing answers it again or sends
            // new words as a message meanwhile.
            assert!(desktop.interaction_submitting());
            assert!(desktop.composer.is_empty());
            assert!(desktop.pending_input_question().is_some());
            assert!(!desktop.pick_ask_choice(0, cx));
            desktop.set_composer_text("Something else".into(), cx);
            desktop.submit_composer(false, cx);
            assert!(desktop.pending_send.is_none());
            assert!(desktop.model.queue.is_empty());
            desktop.set_composer_text(String::new(), cx);
        });
        reply_to_respond(
            &desktop,
            &mut requests,
            &updates,
            serde_json::json!({"ok": false, "error": "The request is no longer waiting."}),
            cx,
        );
        cx.update_window_entity(&desktop, |desktop, _, _| {
            assert!(!desktop.interaction_submitting());
            assert_eq!(desktop.composer, "Staging only", "the words come back");
            assert!(desktop.draft_dirty, "and go back to the draft");
            assert_eq!(
                desktop.model.connection_error.as_deref(),
                Some("The request is no longer waiting.")
            );
            assert!(desktop.kept_answer("ask-1", "q0").is_none());
            assert!(
                desktop.typed_answer().is_some(),
                "the question takes an answer again"
            );
        });

        // Tried again and taken.
        let send = cx.debug_bounds("native-send-message").unwrap();
        cx.simulate_click(send.center(), gpui::Modifiers::default());
        cx.run_until_parked();
        reply_to_respond(
            &desktop,
            &mut requests,
            &updates,
            serde_json::json!({"ok": true}),
            cx,
        );
        cx.update_window_entity(&desktop, |desktop, _, _| {
            assert!(!desktop.interaction_submitting());
            assert!(desktop.composer.is_empty());
        });
    }

    #[gpui::test]
    fn a_chat_newly_stopped_at_its_quota_is_announced_once(cx: &mut gpui::TestAppContext) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            desktop.settings.notifications = false;
            desktop.model = grouped_workspace_fixture();
            let stop = |desktop: &mut XdDesktop, id: &str| {
                if let Some(chat) = desktop.model.chats.iter_mut().find(|chat| chat.id == id) {
                    chat.quota_reached = true;
                }
            };
            // Chats already stopped when xd first sees the tree stay quiet.
            let first = desktop.model.chats[0].id.clone();
            stop(desktop, &first);
            desktop.notify_new_quota_stops(cx);
            assert!(desktop.quota_stops_announced.is_empty());

            // One that stops later is announced, once.
            let second = desktop.model.chats[1].id.clone();
            stop(desktop, &second);
            desktop.notify_new_quota_stops(cx);
            assert!(desktop.quota_stops_announced.contains(&second));
            assert!(!desktop.quota_stops_announced.contains(&first));
            desktop.notify_new_quota_stops(cx);
            assert_eq!(desktop.quota_stops_announced.len(), 1);

            // Going on forgets it, so a later stop is announced again.
            for chat in &mut desktop.model.chats {
                chat.quota_reached = false;
            }
            desktop.notify_new_quota_stops(cx);
            assert!(desktop.quota_stops_announced.is_empty());
        });
    }

    #[cfg(unix)]
    #[gpui::test]
    fn the_chat_quota_setting_shows_only_on_a_host_that_has_quotas(cx: &mut gpui::TestAppContext) {
        use std::os::unix::net::UnixStream;

        let (client, server) = UnixStream::pair().unwrap();
        server
            .set_read_timeout(Some(Duration::from_secs(2)))
            .unwrap();
        let (host, _updates) = HostHandle::connect_io(
            client.try_clone().unwrap(),
            client,
            PathBuf::from("chat-quota-settings-test"),
        );
        let mut requests = std::io::BufReader::new(server);
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        cx.update_window_entity(&desktop, |desktop, _, cx| {
            let colors = desktop.settings.theme.colors();
            desktop.host = Some(host.clone());
            desktop.model.connected = true;
            desktop.minimal_theme_open = true;
            // An older host is never asked.
            desktop.request_chat_quota_settings();
            desktop.chat_quota = Some(ChatQuotaSettings { percent: None });
            assert!(desktop.chat_quota_rows(colors, cx).is_empty());

            desktop.chat_quota = None;
            let tree =
                serde_json::json!({"ok": true, "folders": [], "chats": [], "chat_quotas": true});
            desktop.handle_reply(
                RequestKind::Tree,
                tree.as_object().unwrap().clone(),
                None,
                cx,
            );
            assert!(desktop.model.chat_quotas_supported);
            desktop.handle_reply(
                RequestKind::ChatQuotaSettings { broadcasts: 0 },
                serde_json::json!({"ok": true, "percent": null})
                    .as_object()
                    .unwrap()
                    .clone(),
                None,
                cx,
            );
            assert_eq!(
                desktop.chat_quota,
                Some(ChatQuotaSettings { percent: None })
            );
            assert_eq!(
                desktop.chat_quota_rows(colors, cx).len(),
                1,
                "off: just the switch"
            );

            desktop.handle_event(
                "chat-quota-settings",
                serde_json::json!({"percent": 15}),
                None,
                cx,
            );
            assert_eq!(
                desktop.chat_quota,
                Some(ChatQuotaSettings { percent: Some(15) })
            );
            assert_eq!(desktop.chat_quota_rows(colors, cx).len(), 2);

            desktop.change_chat_quota_settings(ChatQuotaSettings { percent: None }, cx);
            // Another client's change broadcast after this request is newer
            // than the reply to it, which must not undo it.
            desktop.handle_event(
                "chat-quota-settings",
                serde_json::json!({"percent": 30}),
                None,
                cx,
            );
            desktop.handle_reply(
                RequestKind::SetChatQuotaSettings { broadcasts: 1 },
                serde_json::json!({"ok": true, "percent": null})
                    .as_object()
                    .unwrap()
                    .clone(),
                None,
                cx,
            );
            assert_eq!(
                desktop.chat_quota,
                Some(ChatQuotaSettings { percent: Some(30) })
            );
            // Overlapping requests each keep their own place: an older one's
            // reply arriving after a newer request was sent still loses to the
            // broadcast between them, and the newer one's reply applies.
            let reply = |percent: Value| {
                serde_json::json!({"ok": true, "percent": percent})
                    .as_object()
                    .unwrap()
                    .clone()
            };
            let older = desktop.chat_quota_broadcasts;
            desktop.handle_event(
                "chat-quota-settings",
                serde_json::json!({"percent": 40}),
                None,
                cx,
            );
            let newer = desktop.chat_quota_broadcasts;
            desktop.handle_reply(
                RequestKind::ChatQuotaSettings { broadcasts: older },
                reply(Value::Null),
                None,
                cx,
            );
            assert_eq!(
                desktop.chat_quota,
                Some(ChatQuotaSettings { percent: Some(40) })
            );
            desktop.handle_reply(
                RequestKind::ChatQuotaSettings { broadcasts: newer },
                reply(serde_json::json!(40)),
                None,
                cx,
            );
            assert_eq!(
                desktop.chat_quota,
                Some(ChatQuotaSettings { percent: Some(40) })
            );
        });
        // The first request the desktop sent is the tree's ask, not one before it.
        let mut first = String::new();
        std::io::BufRead::read_line(&mut requests, &mut first).unwrap();
        assert_eq!(
            serde_json::from_str::<Value>(&first).unwrap()["op"],
            "chat-quota-settings"
        );
        let request = next_request_with_op(&mut requests, "set-chat-quota-settings");
        assert!(request["percent"].is_null());
    }

