    #[gpui::test]
    fn agents_sessions_start_folded_under_the_session_that_started_them(
        cx: &mut gpui::TestAppContext,
    ) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update_in(cx, |desktop, window, cx| {
            desktop.active_endpoint = ChatEndpoint::Local;
            desktop.expanded_sessions.clear();
            desktop.settings.expanded_session_sets.clear();
            desktop.model.folders = vec![Folder {
                id: "fold-project".into(),
                name: "Fold".into(),
                parent: None,
                owner: None,
                group: false,
            }];
            let chat = |id: &str| -> ChatSummary {
                serde_json::from_value(serde_json::json!({
                    "id": id,
                    "folder": "fold-project",
                    "backend": "codex",
                }))
                .unwrap()
            };
            let session = |id: &str, parent: Option<&str>| xd_desktop::model::SessionSummary {
                id: id.into(),
                folder: "fold-project".into(),
                title: id.into(),
                chats: vec![format!("{id}-chat")],
                branch: None,
                working: false,
                terminal_working: false,
                background_tasks: 0,
                terminal_chat: String::new(),
                parent: parent.map(Into::into),
            };
            desktop.model.chats = vec![chat("lead-chat"), chat("worker-chat"), chat("deep-chat")];
            desktop.model.sessions = vec![
                session("lead", None),
                session("worker", Some("lead")),
                session("deep", Some("worker")),
            ];

            // Nobody has unfolded anything yet, so every lead lists folded;
            // a search still shows every match.
            assert!(desktop.session_folded("lead", false));
            assert!(desktop.session_folded("worker", false));
            assert!(!desktop.session_folded("lead", true));

            desktop.toggle_session_folded("lead".into(), cx);
            assert!(!desktop.session_folded("lead", false));
            assert_eq!(
                desktop.settings.expanded_session_sets.get("local"),
                Some(&vec!["lead".to_owned()])
            );
            desktop.toggle_session_folded("lead".into(), cx);
            assert!(desktop.session_folded("lead", false));
            assert!(!desktop.settings.expanded_session_sets.contains_key("local"));

            // Opening a session deep down unfolds every session above it, so
            // its row shows; the session itself keeps its own fold.
            desktop.open_agent_chat("deep-chat", window, cx);
            assert!(!desktop.session_folded("lead", false));
            assert!(!desktop.session_folded("worker", false));
            assert!(desktop.session_folded("deep", false));
            assert_eq!(
                desktop.settings.expanded_session_sets.get("local"),
                Some(&vec!["lead".to_owned(), "worker".to_owned()])
            );

            // So does a session the app picks by itself, such as the next one
            // after settling the open session.
            desktop.toggle_session_folded("lead".into(), cx);
            assert!(desktop.session_folded("lead", false));
            desktop.select_minimal_session(
                "fold-project".into(),
                "worker-chat".into(),
                AgentCli::Codex,
                cx,
            );
            assert!(!desktop.session_folded("lead", false));
        });
    }

    #[gpui::test]
    fn a_lead_waits_on_its_agents_and_finished_agents_leave_the_sidebar(
        cx: &mut gpui::TestAppContext,
    ) {
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, _| {
            desktop.active_endpoint = ChatEndpoint::Local;
            desktop.model.folders = vec![Folder {
                id: "agents-project".into(),
                name: "Agents".into(),
                parent: None,
                owner: None,
                group: false,
            }];
            let chat = |id: &str, working: bool| -> ChatSummary {
                serde_json::from_value(serde_json::json!({
                    "id": id,
                    "folder": "agents-project",
                    "backend": "claude",
                    "working": working,
                }))
                .unwrap()
            };
            let session = |id: &str, chats: &[&str], parent: Option<&str>| {
                xd_desktop::model::SessionSummary {
                    id: id.into(),
                    folder: "agents-project".into(),
                    title: id.into(),
                    chats: chats.iter().map(|chat| (*chat).into()).collect(),
                    branch: None,
                    working: false,
                    terminal_working: false,
                    background_tasks: 0,
                    terminal_chat: format!("session:{id}"),
                    parent: parent.map(Into::into),
                }
            };
            // The lead started an agent in a worktree of its own, one in its
            // own worktree (a tab of its session), and one that is done.
            desktop.model.chats = vec![
                chat("lead-chat", false),
                chat("tab-chat", true),
                chat("worker-chat", true),
                chat("done-chat", false),
            ];
            desktop.model.sessions = vec![
                session("lead", &["lead-chat", "tab-chat"], None),
                session("worker", &["worker-chat"], Some("lead")),
                session("done", &["done-chat"], Some("lead")),
            ];
            desktop.model.chat_parents = ["tab-chat", "worker-chat", "done-chat"]
                .into_iter()
                .map(|agent| (agent.to_owned(), "lead-chat".to_owned()))
                .collect();
            desktop.settings.session_chats.clear();

            let rows = desktop.catalog_session_chats();
            let row = |id: &str| rows.iter().find(|row| row.id == id).unwrap();
            let card = |id: &str| {
                minimal::project_sessions("agents-project", &rows)
                    .into_iter()
                    .find(|card| card.id == id)
                    .unwrap()
            };
            // The lead does no work of its own: it waits on its two agents at
            // work, as on background shells, rather than taking on their dots.
            assert!(!row("lead-chat").working);
            assert_eq!(
                desktop.session_signal(&card("lead-chat")),
                SessionSignal::Background(2)
            );
            assert_eq!(
                desktop.session_signal(&card("worker-chat")),
                SessionSignal::Working
            );
            assert_eq!(
                desktop.outward_signal(&card("worker-chat")),
                SessionSignal::Idle
            );

            // Only agents' sessions of their own leave the count and, once
            // done, the sidebar, unless shown or waiting on the user.
            assert!(!desktop.agent_session_row("lead-chat"));
            assert!(desktop.agent_session_row("worker-chat"));
            let counted = minimal::project_cards(&desktop.model.folders, &rows, |chat| {
                desktop.agent_session_row(&chat.id)
            })[0]
                .counted;
            assert_eq!(counted, 1);
            assert!(!desktop.finished_agent_row(row("worker-chat"), None));
            assert!(desktop.finished_agent_row(row("done-chat"), None));
            assert!(!desktop.finished_agent_row(row("done-chat"), Some("done-chat")));
            // A finished agent tab the user has not read leaves the lead quiet,
            // as does a paused one; one waiting on the user still shows.
            desktop.model.chats[1].working = false;
            desktop.model.chats[1].paused = true;
            desktop.model.unread_chats.insert("tab-chat".into());
            let rows = desktop.catalog_session_chats();
            let lead = minimal::project_sessions("agents-project", &rows)
                .into_iter()
                .find(|card| card.id == "lead-chat")
                .unwrap();
            assert_eq!(desktop.session_signal(&lead), SessionSignal::Background(1));
            desktop.model.question_chats.insert("tab-chat".into());
            assert_eq!(desktop.session_signal(&lead), SessionSignal::Waiting);
            desktop.model.question_chats.insert("done-chat".into());
            assert!(!desktop.finished_agent_row(row("done-chat"), None));
            assert_eq!(
                desktop.outward_signal(&card("done-chat")),
                SessionSignal::Waiting
            );
        });
    }

    #[gpui::test]
    fn the_session_header_opens_the_branchs_pull_request_in_the_side_browser(
        cx: &mut gpui::TestAppContext,
    ) {
        let url = "http://localhost:3000/o/r/pull/173";
        let (desktop, cx) = cx.add_window_view(XdDesktop::new);
        desktop.update(cx, |desktop, cx| {
            desktop.active_endpoint = ChatEndpoint::Local;
            desktop.set_browser_open(false);
            desktop.settings.browser_sessions.clear();
            desktop.model.folders = vec![Folder {
                id: "pr-project".into(),
                name: "Pull requests".into(),
                parent: None,
                owner: None,
                group: false,
            }];
            desktop.model.chats = vec![
                serde_json::from_value(serde_json::json!({
                    "id": "pr-chat",
                    "folder": "pr-project",
                    "backend": "codex",
                    "branch": "feature",
                }))
                .unwrap(),
            ];
            desktop.model.select_chat("pr-chat");
            desktop.minimal_route = MinimalRoute::Cli {
                project_id: "pr-project".into(),
                chat_id: "pr-chat".into(),
                agent: AgentCli::Codex,
            };
            let mut known = ChatPullRequest::default();
            let lookup = known.start_lookup(Instant::now());
            desktop
                .chat_pull_requests
                .insert((ChatEndpoint::Local, "pr-chat".into()), known);
            desktop.handle_event(
                "git-state",
                serde_json::json!({
                    "chat": "pr-chat",
                    "request": lookup,
                    "pull_request": {"branch": "feature", "url": url},
                }),
                None,
                cx,
            );
            cx.notify();
        });
        cx.run_until_parked();

        let chip = cx
            .debug_bounds("minimal-session-pull-request")
            .expect("the header shows the branch's pull request");
        cx.simulate_click(chip.center(), gpui::Modifiers::default());
        cx.run_until_parked();

        desktop.update(cx, |desktop, cx| {
            assert!(desktop.browser_is_open());
            let pane = desktop.browser_panes["local/chat/pr-chat"].clone();
            assert_eq!(pane.read(cx).current_url().as_deref(), Some(url));
        });
        assert!(cx.opened_url().is_none(), "it stays inside the app");

        // Ctrl+click (Cmd+click on macOS) opens it in the computer's browser.
        cx.update(|_, cx| desktop.read(cx).browser_panes["local/chat/pr-chat"].clone())
            .update(cx, |pane, cx| {
                pane.navigate("http://localhost:3000/elsewhere", cx)
            });
        let chip = cx
            .debug_bounds("minimal-session-pull-request")
            .expect("the chip stays in the header");
        cx.simulate_click(chip.center(), gpui::Modifiers::secondary_key());
        cx.run_until_parked();
        assert_eq!(cx.opened_url().as_deref(), Some(url));
        desktop.update(cx, |desktop, cx| {
            let pane = desktop.browser_panes["local/chat/pr-chat"].clone();
            assert_eq!(
                pane.read(cx).current_url().as_deref(),
                Some("http://localhost:3000/elsewhere"),
                "the browser pane keeps its page"
            );
        });
    }

    fn show_linked_pull_requests(
        desktop: &mut XdDesktop,
        links: serde_json::Value,
        cx: &mut Context<XdDesktop>,
    ) {
        desktop.active_endpoint = ChatEndpoint::Local;
        desktop.set_browser_open(false);
        desktop.settings.browser_sessions.clear();
        let tree = serde_json::json!({
            "folders": [{"id": "pr-project", "name": "Pull requests"}],
            "chats": [{
                "id": "pr-chat",
                "folder": "pr-project",
                "backend": "codex",
                "branch": "feature",
                "pull_requests": links,
            }],
            "linked_pull_requests": true,
        });
        desktop.model.apply_tree(&tree).unwrap();
        desktop.model.select_chat("pr-chat");
        desktop.minimal_route = MinimalRoute::Cli {
            project_id: "pr-project".into(),
            chat_id: "pr-chat".into(),
            agent: AgentCli::Codex,
        };
        cx.notify();
    }

