    fn optimistic_chat_reorder_preserves_other_workspace_positions() {
        let chat = |id: &str, folder: &str| ChatSummary {
            id: id.into(),
            folder: folder.into(),
            title: Some(id.into()),
            backend: "codex".into(),
            branch: None,
            working: false,
            terminal_working: false,
            background_tasks: 0,
            settled_at: None,
            auto_settle_disabled: false,
            paused: false,
            quota_reached: false,
            pull_requests: Vec::new(),
        };
        let mut chats = vec![
            chat("a", "workspace"),
            chat("x", "other"),
            chat("b", "workspace"),
            chat("c", "workspace"),
        ];

        assert!(apply_optimistic_chat_reorder(
            &mut chats,
            &ChatReorder {
                chat_id: "a".into(),
                anchor_id: "c".into(),
                after: true,
            }
        ));
        assert_eq!(
            chats
                .iter()
                .map(|chat| chat.id.as_str())
                .collect::<Vec<_>>(),
            vec!["x", "b", "c", "a"]
        );
    }

